select m.member_month, m.member_id, m.month_start, m.valid_order_cnt, m.net_cents from {{ ref('member_month_valid_orders') }} m where exists (select 1 from {{ ref('cards') }} c where c.member_id = m.member_id and c.card_type in ('悦享年卡','家庭季卡') and c.valid_from <= last_day(m.month_start) and c.valid_until > last_day(m.month_start) and (c.ended_at is null or c.ended_at > last_day(m.month_start)))